import unittest
from candidate import is_palindrome, make_palindrome

class TestStringFunctions(unittest.TestCase):
    def test_is_palindrome_normalcase_true(self):
        self.assertTrue(is_palindrome('racecar'))

    def test_is_palindrome_normalcase_false(self):
        self.assertFalse(is_palindrome('hello'))

    def test_is_palindrome_case_insensitive(self):
        self.assertTrue(is_palindrome('Racecar'.lower()))
        self.assertTrue(is_palindrome('rACECAR'.upper()))

    def test_is_palindrome_empty_string(self):
        self.assertTrue(is_palindrome(''))

    def test_is_palindrome_single_character(self):
        self.assertTrue(is_palindrome('a'))

    def test_is_palindrome_boundary_conditions(self):
        self.assertTrue(is_palindrome(' '))
        self.assertTrue(is_palindrome('\t'))
        self.assertTrue(is_palindrome('\n'))

    def test_make_palindrome_normalcase(self):
        self.assertEqual(make_palindrome('cat'), 'catac')

    def test_make_palindrome_boundary_conditions(self):
        self.assertEqual(make_palindrome('c'), 'c')
        self.assertEqual(make_palindrome(' '), '')

    def test_make_palindrome_empty_string(self):
        self.assertEqual(make_palindrome(''), '')

    def test_make_palindrome_single_character(self):
        self.assertEqual(make_palindrome('a'), 'a')

    def test_make_palindrome_longer_strings(self):
        self.assertEqual(make_palindrome('cata'), 'catac')
        self.assertEqual(make_palindrome('catalina'), 'catalinacatinalac')
        self.assertEqual(make_palindrome('catalinacatinalac'), 'catalinacatinalacatinalinacat')

    def test_make_palindrome_edge_cases(self):
        self.assertEqual(make_palindrome('catat'), 'catcat')
        self.assertEqual(make_palindrome('cataat'), 'catacata')
        self.assertEqual(make_palindrome('catata'), 'catatacata')

if __name__ == '__main__':
    unittest.main()
